1	package ociresources
2	
3	import (
4		tea "charm.land/bubbletea/v2"
5		"fmt"
6		"slices"
7		"strings"
8		"testing"
9	
10		"github.com/charmbracelet/x/ansi"
11	
12		"github.com/anthnel/devdesk/internal/cache"
13		"github.com/anthnel/devdesk/internal/config"
14		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
15		"github.com/anthnel/devdesk/internal/ui/datatable"
16		"github.com/anthnel/devdesk/internal/ui/testutil"
17		"github.com/anthnel/devdesk/internal/ui/theme"
18	)
19	
20	// DEVDESK-510 (NX-07), step 4: what a refused group says, and where. Red phase.
21	//
22	// Formats decided with the UX answer (US English, plain text in cells, Rule 122):
23	//
24	//	Members cell, refused, nothing listed:  "denied · <TimeAgo(refusal.At)>"
25	//	Members cell, refused, N members known: "denied · N known · <TimeAgo(refusal.At)>"
26	//	  (the state comes first, the count last known stays visible, D23; the age is
27	//	  the refusal's, the last attempt. The column has to be wide enough to hold it
28	//	  whole: the tests read the rendered row, not only the cell.)
29	//	Members cell, settled empty:            "0 · <TimeAgo>"  (unchanged)
30	//	Members cell, never probed:             "never"          (unchanged)
31	//	Members cell, listing newer than the refusal: the refusal is stale and the
32	//	  cell is the plain "N · <TimeAgo(listing)>".
33	//
34	// Status line (derived on every render, no timer, no new shortcut):
35	//
36	//	refused:                   Warn  "Members could not be read with this account — declare them by hand with repo_prefix"
37	//	refused, N declared:       Warn  "Members could not be read with this account — N declared by hand are used"
38	//	settled empty (0 members): Info  "No member found — this group is empty"
39	//
40	// The footer is never the only trace: the cell carries the state as a word.
41	
42	const (
43		statusRefusedLine  = "Members could not be read with this account — declare them by hand with repo_prefix"
44		statusDeclaredFmt  = "Members could not be read with this account — %d declared by hand are used"
45		statusEmptyGroup   = "No member found — this group is empty"
46		drillInNoMembers   = "No members to open — declare them by hand with repo_prefix"
47		registryHostInTest = "registry.example.com"
48	)
49	
50	// refusalCases are the three refusals the wording must handle (CA4).
51	var refusalCases = []struct {
52		name    string
53		refusal cache.RegistryGroupRefusal
54	}{
55		{"403 account", cache.RegistryGroupRefusal{At: at(7), Status: 403}},
56		{"401 account", cache.RegistryGroupRefusal{At: at(7), Status: 401}},
57		{"anonymous", cache.RegistryGroupRefusal{At: at(7), Status: 403, Anonymous: true}},
58	}
59	
60	// wantRefusalText checks what every refusal text shares: plain text, English
61	// punctuation only, no raw error, no URL, and nothing that reads as an empty group.
62	func wantRefusalText(t *testing.T, what, text string) {
63		t.Helper()
64		if strings.Contains(text, "\x1b") {
65			t.Errorf("%s = %q carries an escape sequence (Rule 122)", what, text)
66		}
67		for _, r := range text {
68			if r > 0x7e && r != '—' && r != '·' {
69				t.Errorf("%s = %q holds %q: US English only (Rule 129)", what, text, r)
70				break
71			}
72		}
73		for _, bad := range []string{"management API returned", registryHostInTest, "docker-group", "http", "0 members", "empty", "No member found"} {
74			if strings.Contains(text, bad) {
75				t.Errorf("%s = %q contains %q: a refusal must not leak the error or read as an empty group", what, text, bad)
76			}
77		}
78	}
79	
80	func wantAll(t *testing.T, what, text string, words ...string) {
81		t.Helper()
82		for _, w := range words {
83			if !strings.Contains(text, w) {
84				t.Errorf("%s = %q, want it to contain %q", what, text, w)
85			}
86		}
87	}
88	
89	// ── The pure wording (H2, H3, H4) ───────────────────────────────────────────
90	
91	func TestRefusedMembersCellSaysDeniedAndWhen(t *testing.T) {
92		for _, tc := range refusalCases {
93			t.Run(tc.name, func(t *testing.T) {
94				ago := theme.TimeAgo(tc.refusal.At)
95	
96				got := refusedMembersCell(groupRefusalView{Refusal: tc.refusal})
97				if want := "denied · " + ago; got != want {
98					t.Errorf("nothing listed: cell = %q, want %q", got, want)
99				}
100				wantRefusalText(t, "cell", got)
101	
102				got = refusedMembersCell(groupRefusalView{Refusal: tc.refusal, Known: 3})
103				if !strings.HasPrefix(got, "denied") {
104					t.Errorf("3 known: cell = %q, want the state first", got)
105				}
106				wantAll(t, "3 known: cell", got, "3 known", ago)
107				wantRefusalText(t, "cell", got)
108			})
109		}
110	}
111	
112	func TestRefusedStatusLineWording(t *testing.T) {
113		for _, tc := range refusalCases {
114			t.Run(tc.name, func(t *testing.T) {
115				none := refusedStatusLine(groupRefusalView{Refusal: tc.refusal})
116				declared := refusedStatusLine(groupRefusalView{Refusal: tc.refusal, Declared: 2})
117				wantAll(t, "status line", none, "repo_prefix")
118				wantRefusalText(t, "status line", none)
119				wantRefusalText(t, "status line (declared)", declared)
120				if !tc.refusal.Anonymous {
121					if none != statusRefusedLine {
122						t.Errorf("status line = %q, want %q", none, statusRefusedLine)
123					}
124					if want := fmt.Sprintf(statusDeclaredFmt, 2); declared != want {
125						t.Errorf("status line with 2 declared = %q, want %q", declared, want)
126					}
127				}
128				if declared == none {
129					t.Error("declared members must change the line: it says they are used")
130				}
131			})
132		}
133	}
134	
135	func TestRefusedDrillInTextWording(t *testing.T) {
136		for _, tc := range refusalCases {
137			t.Run(tc.name, func(t *testing.T) {
138				got := refusedDrillInText(groupRefusalView{Refusal: tc.refusal})
139				wantAll(t, "drill-in text", got, "repo_prefix")
140				wantRefusalText(t, "drill-in text", got)
141				if strings.Contains(got, "ctrl+r") {
142					t.Errorf("drill-in text = %q: ctrl+r cannot help after a refusal", got)
143				}
144				if !tc.refusal.Anonymous && got != drillInNoMembers {
145					t.Errorf("drill-in text = %q, want %q", got, drillInNoMembers)
146				}
147			})
148		}
149	}
150	
151	// ── H1: the footer after a refused ctrl+r ───────────────────────────────────
152	
153	func TestTheFooterAfterARefusedRefreshExplainsAndStaysAWarning(t *testing.T) {
154		for _, tc := range []struct {
155			name  string
156			err   error
157			words []string
158		}{
159			{"account 403", refusalOf(403, false), []string{"could not be read", "this account", "repo_prefix"}},
160			{"account 401", refusalOf(401, false), []string{"could not be read", "this account", "repo_prefix"}},
161			{"anonymous", refusalOf(403, true), []string{"repo_prefix"}},
162		} {
163			t.Run(tc.name, func(t *testing.T) {
164				m := groupModel(t)
165				m = feed(t, m, RegistryGroupDetectedMsg{RegistryURL: registryHostInTest, Slug: "prod", Err: tc.err, At: at(7)})
166	
167				if m.footer.Level() != sharedcomponents.LevelWarning {
168					t.Errorf("footer level = %v, want Warn (%q)", m.footer.Level(), m.footer.Text())
169				}
170				wantAll(t, "footer", m.footer.Text(), tc.words...)
171				wantRefusalText(t, "footer", m.footer.Text())
172				if strings.Contains(m.footer.Text(), tc.err.Error()) {
173					t.Errorf("footer = %q carries the error text", m.footer.Text())
174				}
175			})
176		}
177	}
178	
179	// ── H2/H3 through the model ─────────────────────────────────────────────────
180	
181	func listing(members int, day int) *cache.RegistryGroupEntry {
182		e := cache.RegistryGroupEntry{DiscoveredAt: at(day)}
183		for i := range members {
184			e.Members = append(e.Members, cache.RegistryGroupMember{
185				Alias: fmt.Sprintf("m%d", i), URL: registryHostInTest, RepoPrefix: fmt.Sprintf("m%d", i),
186			})
187		}
188		return &e
189	}
190	
191	// tabWith is the Registries tab, group row selected, with the cache the test hands in.
192	func tabWith(t *testing.T, cfg *config.Config, entry *cache.RegistryGroupEntry, refusal *cache.RegistryGroupRefusal) Model {
193		t.Helper()
194		m := feed(t, New(cfg), tea.WindowSizeMsg{Width: 180, Height: 30},
195			ImagesListMsg{Images: imageFixtures()}, NetworksListMsg{Networks: networkFixtures()}, VolumesListMsg{Volumes: volumeFixtures()})
196		loaded := RegistryGroupCacheLoadedMsg{Entries: map[string]cache.RegistryGroupEntry{}}
197		if entry != nil {
198			loaded.Entries["prod"] = *entry
199		}
200		if refusal != nil {
201			loaded.Refusals = map[string]cache.RegistryGroupRefusal{"prod": *refusal}
202		}
203		m = feed(t, m, loaded)
204		for m.activeTab != tabRegistries {
205			m = feed(t, m, testutil.Key("tab"))
206		}
207		return m
208	}
209	
210	func refusalAt(day int) *cache.RegistryGroupRefusal {
211		return &cache.RegistryGroupRefusal{At: at(day), Status: 403}
212	}
213	
214	func TestTheMembersCellOfEachState(t *testing.T) {
215		cases := []struct {
216			name    string
217			entry   *cache.RegistryGroupEntry
218			refusal *cache.RegistryGroupRefusal
219			want    func(cell string) string // empty string = pass, else the complaint
220		}{
221			{"never probed", nil, nil, exactly("never")},
222			{"listed", listing(2, 3), nil, exactly("2 · " + theme.TimeAgo(at(3)))},
223			{"settled empty", listing(0, 3), nil, exactly("0 · " + theme.TimeAgo(at(3)))},
224			{"refused, never listed", nil, refusalAt(7), exactly("denied · " + theme.TimeAgo(at(7)))},
225			{"refused after an empty listing", listing(0, 3), refusalAt(7), exactly("denied · " + theme.TimeAgo(at(7)))},
226			{"refused, 2 members known", listing(2, 3), refusalAt(7), func(c string) string {
227				if !strings.HasPrefix(c, "denied") || !strings.Contains(c, "2 known") || !strings.Contains(c, theme.TimeAgo(at(7))) {
228					return "want denied first, the 2 members known and the age of the refusal"
229				}
230				return ""
231			}},
232			{"stale refusal, listing is newer", listing(2, 9), refusalAt(7), exactly("2 · " + theme.TimeAgo(at(9)))},
233		}
234		for _, tc := range cases {
235			t.Run(tc.name, func(t *testing.T) {
236				m := tabWith(t, testConfig(), tc.entry, tc.refusal)
237				cell := m.registryTable.Table().Rows()[0][membersCol]
238	
239				if complaint := tc.want(cell); complaint != "" {
240					t.Errorf("Members cell = %q: %s", cell, complaint)
241				}
242				if strings.Contains(cell, "\x1b") {
243					t.Errorf("Members cell = %q carries an escape sequence (Rule 122)", cell)
244				}
245				// The column must be wide enough to hold the whole word and age.
246				if line := ansi.Strip(renderedRow(t, m.registryTable.View(), "prod")); !strings.Contains(line, cell) {
247					t.Errorf("the rendered row does not hold the whole cell %q:\n%s", cell, line)
248				}
249			})
250		}
251	}
252	
253	func exactly(want string) func(string) string {
254		return func(got string) string {
255			if got != want {
256				return fmt.Sprintf("want %q", want)
257			}
258			return ""
259		}
260	}
261	
262	func TestARefusedRowIsFlaggedForItsStyleOnly(t *testing.T) {
263		m := tabWith(t, testConfig(), listing(2, 3), refusalAt(7))
264		items := m.registryTable.Items()
265		if !items[0].membersRefused {
266			t.Error("the refused group's row is not flagged membersRefused")
267		}
268		if items[1].membersRefused {
269			t.Error("another registry's row is flagged membersRefused")
270		}
271	
272		var members datatable.Column[registryRow]
273		for _, col := range registryColumns() {
274			if col.Title == "Members" {
275				members = col
276			}
277		}
278		refused := members.Style(registryRow{membersRefused: true}).Render("denied")
279		plain := members.Style(registryRow{}).Render("denied")
280		if refused == plain {
281			t.Error("the Members column renders a refused row like any other: the colour must not be the only carrier, but it must differ")
282		}
283	
284		stale := tabWith(t, testConfig(), listing(2, 9), refusalAt(7))
285		if stale.registryTable.Items()[0].membersRefused {
286			t.Error("a refusal older than the listing still flags the row")
287		}
288	}
289	
290	func TestTheStatusLineFollowsTheSelectedGroupRow(t *testing.T) {
291		cases := []struct {
292			name      string
293			entry     *cache.RegistryGroupEntry
294			refusal   *cache.RegistryGroupRefusal
295			wantText  string
296			wantLevel sharedcomponents.Level
297		}{
298			{"refused, never listed", nil, refusalAt(7), statusRefusedLine, sharedcomponents.LevelWarning},
299			{"refused, 2 known", listing(2, 3), refusalAt(7), statusRefusedLine, sharedcomponents.LevelWarning},
300			{"settled empty", listing(0, 3), nil, statusEmptyGroup, sharedcomponents.LevelInfo},
301			{"refused after an empty listing", listing(0, 3), refusalAt(7), statusRefusedLine, sharedcomponents.LevelWarning},
302			{"listed", listing(2, 3), nil, "", sharedcomponents.LevelInfo},
303			{"never probed", nil, nil, "", sharedcomponents.LevelInfo},
304			{"stale refusal", listing(2, 9), refusalAt(7), "", sharedcomponents.LevelInfo},
305		}
306		for _, tc := range cases {
307			t.Run(tc.name, func(t *testing.T) {
308				m := tabWith(t, testConfig(), tc.entry, tc.refusal)
309				st := m.status()
310				if st.Text != tc.wantText || (tc.wantText != "" && st.Level != tc.wantLevel) {
311					t.Errorf("status = %q at level %v, want %q at level %v", st.Text, st.Level, tc.wantText, tc.wantLevel)
312				}
313				if tc.wantText != "" {
314					m = feed(t, m, testutil.Key("down"))
315					if got := m.status().Text; got != "" {
316						t.Errorf("another row selected: status = %q, want nothing: the line belongs to the group row", got)
317					}
318				}
319			})
320		}
321	}
322	
323	func TestTheStatusLineCountsTheMembersDeclaredByHand(t *testing.T) {
324		m := tabWith(t, declaredConfig(), nil, refusalAt(7))
325		st := m.status()
326		if want := fmt.Sprintf(statusDeclaredFmt, 1); st.Text != want || st.Level != sharedcomponents.LevelWarning {
327			t.Errorf("status = %q at level %v, want Warn %q", st.Text, st.Level, want)
328		}
329	}
330	
331	func TestDeclaredMembersCountsTheEntriesOfOneGroup(t *testing.T) {
332		regs := declaredConfig().Registry.Registries
333		regs = append(regs,
334			config.RegistryItem{Slug: "other", Kind: config.KindRegistry, Parent: "elsewhere", URL: registryHostInTest, RepoPrefix: "x", AuthMode: config.AuthInherit},
335			config.RegistryItem{Slug: "dhi2", Kind: config.KindRegistry, Parent: "prod", URL: registryHostInTest, RepoPrefix: "dhi2", AuthMode: config.AuthInherit})
336		if got := declaredMembers(regs, "prod"); got != 2 {
337			t.Errorf("declaredMembers(prod) = %d, want 2", got)
338		}
339		if got := declaredMembers(regs, "nobody"); got != 0 {
340			t.Errorf("declaredMembers(nobody) = %d, want 0", got)
341		}
342	}
343	
344	// The state is held by the cell and the status line, not by the 3-second footer:
345	// once the message expires, the refusal is still on screen.
346	func TestTheRefusalOutlivesItsFooterMessage(t *testing.T) {
347		m := groupModel(t)
348		m = feed(t, m, RegistryGroupDetectedMsg{RegistryURL: registryHostInTest, Slug: "prod", Err: refusalOf(403, false), At: at(7)})
349		m = feed(t, m, sharedcomponents.ClearFooterMsg{ID: m.footer.ID()})
350	
351		if m.footer.IsSet() {
