60	// wantRefusalText checks what every refusal text shares: plain text, English
61	// punctuation only, no raw error, no URL, and nothing that reads as an empty group.
62	func wantRefusalText(t *testing.T, what, text string) {
63		t.Helper()
64		if strings.Contains(text, "\x1b") {
65			t.Errorf("%s = %q carries an escape sequence (Rule 122)", what, text)
66		}
67		for _, r := range text {
68			if r > 0x7e && r != '—' && r != '·' {
69				t.Errorf("%s = %q holds %q: US English only (Rule 129)", what, text, r)
70				break
71			}
72		}
73		for _, bad := range []string{"management API returned", registryHostInTest, "docker-group", "http", "0 members", "empty", "No member found"} {
74			if strings.Contains(text, bad) {
75				t.Errorf("%s = %q contains %q: a refusal must not leak the error or read as an empty group", what, text, bad)
76			}
77		}
78	}
79	
80	func wantAll(t *testing.T, what, text string, words ...string) {
81		t.Helper()
82		for _, w := range words {
83			if !strings.Contains(text, w) {
84				t.Errorf("%s = %q, want it to contain %q", what, text, w)
85			}
86		}
87	}
