}

// refusedFooterText is the footer line after a refused refresh. Provisional
// wording, kept in this one place until the UX text of step 4 replaces it. It
// never carries the manager's error text or the registry URL.
func refusedFooterText(r cache.RegistryGroupRefusal) string {
	if r.Anonymous {
		return "Members not listed: the manager refuses anonymous access — set credentials or declare them with repo_prefix"
	}
	return "Members not listed: the manager refused this account — declare them with repo_prefix"
}

// toCachedMembers converts what the detector returned into what the cache and
// the table hold.
func toCachedMembers(members []registrymgr.GroupMember) []cache.RegistryGroupMember {
	out := make([]cache.RegistryGroupMember, 0, len(members))
	for _, m := range members {
		out = append(out, cache.RegistryGroupMember{Alias: m.Alias, URL: m.URL, RepoPrefix: m.RepoPrefix})
	}
	return out
}

